    input = sys.stdin.read().split()
    n = int(input[0])
    c = list(map(int, input[1:]))

    def greedy_coins(x):
        count = 0
        for coin in reversed(c):
            while x >= coin:
                x -= coin
                count += 1
        return count

    def optimal_coins(x):
        dp = [float('inf')] * (x + 1)
        dp[0] = 0
        for i in range(1, x + 1):
            for coin in c:
                if i - coin >= 0:
                    dp[i] = min(dp[i], dp[i - coin] + 1)
        return dp[x]

    limit = c[-1] + c[-2]
    for x in range(2, limit):
        if greedy_coins(x) != optimal_coins(x):
            print("non-canonical")
            return

    print("canonical")

